const result = {};
for (const key in form) {
    if (form.hasOwnProperty(key)) {
        const titleCaseKey = key.charAt(0).toUpperCase() + key.slice(1);

        if (form[key] === "") continue;

        // resets
        if (key === "offCycle") {
            const fieldsToReset = [];
            if (!form[key]) {
                fieldsToReset.push("startDate", "endDate", "payDate", "finalPayEligibleWorker", "workingDays");
                if (method === "POST") {
                    fieldsToReset.push("displayName");
                }
            } else {
                fieldsToReset.push("payScheduleId");
            }
            $ctrl.utils.resetDependentFields(fieldsToReset, form);
        }

        if (key === "runType" && form[key] !== "OFFCYCLE") $ctrl.utils.resetDependentFields(["offCycleReason"], form);

        if ((key === "offCycle" || key === "payScheduleId" || key === "startDate" || key === "endDate" || key === "payDate" || key === "payPeriodId" || key === "runType" || key === "finalPayEligibleWorker") && method === "PUT") continue;

        if ((/^(is|need|with|can|allow|active|salaried|enabled|final)/i.test(key) || key.toLowerCase() === "employercontribution") && method === "POST" && key !== "finalPayEligibleWorker") {
            result[titleCaseKey] = form[key] || false;
        } else if (key === "workingDays" && form[key] && Object.values(form[key]).find(day => day)) {
            result[titleCaseKey] = $ctrl.convertWorkingDaysToString(form[key]);
        } else if (key.includes("Date") && form[key]) {
            result[titleCaseKey] = $ctrl.utils.parseDate(form[key]);
        } else {
            result[titleCaseKey] = form[key];
        }
    }
}
return result;

if (method === "POST") $ctrl.uiState.isInserting = true;
if (method === "PUT") $ctrl.uiState.isUpdating = true;
const entityId = $ctrl.uiState.selectedEntity?.Id;

async function updateEditForm() {
    const tableRowIndex = $ctrl.tabStore[$ctrl.uiState.currentTab.name].data.findIndex(entity => entity.Id === entityId);
    if (tableRowIndex === -1) {
        throw new Error(`Entity not found in table`);
    }

    $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = $ctrl.utils.buildUpdatedEntityData($ctrl[$ctrl.tabConfig[$ctrl.uiState.currentTab.name].form], $ctrl.uiState.selectedEntity);

    // Hydrate fields based on updated Ids on dropdown selection
    const hydratedEntity = await $ctrl.referenceDataService.hydrateEntity(
        $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex]
    );
    $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = hydratedEntity
    $ctrl.$timeout(() => {
        $ctrl.utils.setSelectedBelliniTableRow(tableRowIndex);
    });
    $ctrl.handlers.onEditInit();
    const formToReset = document.querySelector('.form');
    if(formToReset) {
        formToReset.scrollTop = 0;
    }
}

$ctrl.payrollAppApi[endpoint](
    {},
    {
        ...$ctrl.buildRequestBody(form, method),
        ...(method === "PUT" ? { "Id": $ctrl.uiState.selectedEntity.Id } : {}),
        ...($ctrl.uiState.isAdding && form.offCycle ? { "CompanyId": $ctrl.globalSelectedCompany.companyId } : {})
    },
    { headers: $ctrl.authCookies.setHeaders() }
).then(async result => {
    $ctrl.utils.toast(`Successfully ${$ctrl.uiState.isInserting ? "added" : "edited"} ${entityName}`, result.data.result);
    if ($ctrl.uiState.isInserting) {
        $ctrl.handlers.onAddInit();
        $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
        $ctrl.utils.resetForm(form);
    }

    if ($ctrl.uiState.isUpdating) {
        try {
            await updateEditForm();
        } catch (uiError) {
            console.error('Failed to refresh form/table after successful update', uiError);
            $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
        }
    };

})
    .catch(reason => {
        $ctrl.utils.toast(reason.data.message, reason.data.result);
    })
    .finally(() => {
        if ($ctrl.uiState.isInserting) $ctrl.uiState.isInserting = false;
        if ($ctrl.uiState.isUpdating) $ctrl.uiState.isUpdating = false;
    });

const toBeDeletedEntity = $ctrl.uiState.selectedEntityName;
const toBeDeletedEntityDetails = $ctrl.utils.legacyGenerateEntityDetails({
    entity: $ctrl.uiState.selectedEntity,
    utils: $ctrl.utils
});

let isConfirmed;
$ctrl.uiState.isDeleting = true;

await $ctrl.$modal.open("delete-entity-modal", {
    props:
    {
        EntityName: toBeDeletedEntity,
        EntityDetails: toBeDeletedEntityDetails
    }
}).then(response => isConfirmed = response.result === "ok");

if (isConfirmed) {
        $ctrl.payrollAppApi[endpoint](
            { 
                id: $ctrl.uiState.selectedEntity.Id
            },
            { headers: $ctrl.authCookies.setHeaders() }
        ).then(result => {
            $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
            // $ctrl.utils.toast(result.data.message, result.data.result);
            // if (result.data.warnings.length > 0) result.data.warnings.forEach(warning => $ctrl.utils.toast(warning.message, result.data.result));
            // else $ctrl.utils.toast(`Successfully deleted ${toBeDeletedEntity}`, result.data.result);
        }).catch(reason => {
            $ctrl.utils.toast(reason.data.message, reason.data.result);
        }).finally(() => {
            $ctrl.uiState.isDeleting = false;
        });

} else {
    $ctrl.uiState.isDeleting = false;
}

$ctrl.uiState.isInserting = true;

switch ($ctrl.uiState.currentTab.name) {
    case "pay_period":
        const currentDate = new Date();
        const isFutureDate = $ctrl.form.generateDate && $ctrl.form.generateDate > currentDate;
        let confirmedGenerationOfFutureDate = false;

        if (isFutureDate) await $ctrl.$modal.open("confirm-action-modal", {
            title: "Generate Pay Periods for Custom Future Date?",
            body: "Generating REGULAR Pay Periods for future dates would prevent creation of REGULAR Pay Periods before the provided custom future date (" + $ctrl.form.generateDate + "). Proceed?"
        }).then(res => {
            if (res.result === "ok") confirmedGenerationOfFutureDate = true;
            else $ctrl.uiState.isInserting = false;
        });

        if (!isFutureDate || (isFutureDate && confirmedGenerationOfFutureDate)) $ctrl.sendData(
            "lonti_app_payroll_service_pay_period_InsertPayPeriod",
            $ctrl.form,
            $ctrl.form.displayName || $ctrl.referenceData.payScheduleMap.find(paySchedule => paySchedule.Id === $ctrl.form.payScheduleId).label,
            "POST"
        );
        else $ctrl.uiState.isInserting = false;
        break;

    case "payroll_run":
        $ctrl.sendData(
            "lonti_app_payroll_service_payroll_run_InsertPayrollRun",
            $ctrl.form1,
            $ctrl.form1.displayName || "PAYROLL RUN FOR " + $ctrl.referenceData.payPeriodMap.find(payPeriod => payPeriod.Id === $ctrl.form1.payPeriodId).label,
            "POST"
        );
        break;
}

$ctrl.uiState.isUpdating = true;

switch ($ctrl.uiState.currentTab.name) {
    case "pay_period":
        $ctrl.sendData(
            "lonti_app_payroll_service_pay_period_UpdatePayPeriod",
            $ctrl.form,
            $ctrl.uiState.selectedEntity.DisplayName,
            "PUT"
        );
        break;

    case "payroll_run":
        $ctrl.sendData(
            "lonti_app_payroll_service_payroll_run_UpdatePayrollRun",
            $ctrl.form1,
            $ctrl.uiState.selectedEntity.DisplayName,
            "PUT"
        );
        break;
}

